<script setup lang="ts">
import { showTags } from '@/services/knowledge'
import { computed,ref } from 'vue'
import { TagsIcon, XIcon } from '@lucide/vue'
import { toast } from 'vue-sonner'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription,DialogFooter } from '@/components/ui/dialog'
import { ToggleGroup,ToggleGroupItem } from '@/components/ui/toggle-group'
import { Input } from '@/components/ui/input'
import { Field,FieldGroup,FieldLabel,FieldDescription } from '@/components/ui/field'
import { documentTags,setDocumentTags,frontmatter } from '@/services/frontmatter'
import { useWorkbench } from '@/stores/workbench'
import { message } from '@/services/api'
import type { Document } from '@/types'
const props=defineProps<{document:Document}>(),emit=defineEmits<{sync:[]}>(),store=useWorkbench(),open=ref(false),selected=ref<string[]>([]),custom=ref(''),snapshot=ref('')
const tags=computed(()=>documentTags(props.document.text)),options=computed(()=>[...new Set([...store.preferences.tags,...selected.value,...tags.value])]),error=computed(()=>frontmatter(props.document.text).error)
const colorOf=(tag:string)=>store.preferences.tagColors[tag]
const chipStyle=(tag:string)=>{const color=colorOf(tag);return color?{borderColor:color,backgroundColor:`color-mix(in srgb, ${color} 12%, var(--background))`}:undefined}
function edit(){emit('sync');snapshot.value=props.document.text;selected.value=[...tags.value];custom.value='';open.value=true}
function add(){const text=custom.value.trim();if(!text||text.length>40||/[\x00-\x1f]/.test(text)){toast.error('标签名称应为 1–40 个字符。');return}if(options.value.length>=100&&!options.value.includes(text)){toast.error('最多 100 个标签');return}if(!store.preferences.tags.includes(text))store.preferences.tags.push(text);if(!selected.value.includes(text))selected.value.push(text);custom.value=''}
function remove(tag:string){selected.value=selected.value.filter(value=>value!==tag)}
function apply(){try{if(props.document.text!==snapshot.value)throw new Error('文档已变化，请重新打开标签设置。');store.change(props.document,setDocumentTags(props.document.text,selected.value),'tags');props.document.generation++;open.value=false;toast.success('文档标签已更新')}catch(e){toast.error(message(e))}}
</script>
<template><div class="document-tags max-w-48 flex-nowrap! shrink-0 overflow-hidden"><Badge v-for="tag in tags.slice(0,2)" :key="tag" variant="outline" class="max-w-20 cursor-pointer truncate" :title="`查看标签 ${tag}`" role="button" tabindex="0" :style="chipStyle(tag)" @click="showTags(tag)" @keydown.enter="showTags(tag)">{{tag}}</Badge><Badge v-if="tags.length>2" variant="secondary" :title="tags.slice(2).join('、')">+{{tags.length-2}}</Badge><Button variant="ghost" size="icon-sm" aria-label="编辑文档标签" title="编辑文档标签" @click="edit"><TagsIcon/></Button></div>
<Dialog v-model:open="open"><DialogContent class="productivity-dialog sm:max-w-lg"><DialogHeader><DialogTitle>文档标签</DialogTitle><DialogDescription>添加或移除当前文档的标签，点击“应用标签”保存。</DialogDescription></DialogHeader><p v-if="error" class="text-destructive" role="alert">{{error}}</p><FieldGroup class="gap-4"><Field class="gap-2"><div class="flex min-h-5 items-center justify-between gap-3"><FieldLabel>已选标签<span v-if="selected.length" class="ml-1.5 font-normal text-muted-foreground">{{selected.length}}</span></FieldLabel><Button v-if="selected.length" variant="ghost" size="sm" class="h-6 px-2 text-xs text-muted-foreground" :disabled="!!error" @click="selected=[]">清空标签</Button></div><div v-if="selected.length" class="flex flex-wrap items-center gap-1.5 rounded-lg border border-input bg-muted/40 p-2.5" aria-label="已选文档标签"><Badge v-for="tag in selected" :key="tag" variant="outline" class="gap-1 bg-background py-1 pr-1" :style="chipStyle(tag)"><span class="max-w-44 truncate" :title="tag">{{tag}}</span><Button variant="ghost" size="icon-xs" class="size-4 shrink-0 rounded-full opacity-60 hover:opacity-100" :aria-label="`移除文档标签 ${tag}`" :disabled="!!error" @click="remove(tag)"><XIcon /></Button></Badge></div><p v-else class="rounded-lg border border-dashed border-input px-3 py-5 text-center text-sm text-muted-foreground" role="status">当前文档未选择标签。</p></Field><Field v-if="options.length" class="gap-2"><FieldLabel>可选标签<span class="ml-1.5 font-normal text-muted-foreground">{{options.length}}</span></FieldLabel><div class="max-h-36 overflow-y-auto rounded-lg border border-input p-2.5"><ToggleGroup v-model="selected" type="multiple" variant="outline" :spacing="1" class="flex-wrap" aria-label="文档标签选择"><ToggleGroupItem v-for="tag in options" :key="tag" :value="tag" class="gap-1.5"><span v-if="colorOf(tag)" class="size-1.5 shrink-0 rounded-full" :style="{backgroundColor:colorOf(tag)}"/>{{tag}}</ToggleGroupItem></ToggleGroup></div></Field><Field class="gap-2"><FieldLabel for="document-new-tag">新标签</FieldLabel><div class="flex gap-2"><Input id="document-new-tag" v-model="custom" placeholder="输入新标签" @keydown.enter.prevent="add"/><Button variant="outline" :disabled="!!error" @click="add">添加</Button></div><FieldDescription>名称 1–40 个字符，添加后会出现在可选标签中。</FieldDescription></Field></FieldGroup><DialogFooter><Button variant="outline" @click="open=false">取消</Button><Button :disabled="!!error" @click="apply">应用标签</Button></DialogFooter></DialogContent></Dialog></template>
